/**
 * Regenerates packages/integrations/src/pdf/fonts.ts.
 *
 * Takes DejaVu Sans, subsets it to the characters a GST invoice prints, and
 * writes the result into a TypeScript module as base64. Run this only when
 * the invoice needs a character the current subset does not carry.
 *
 * Needs fonttools (`pip install fonttools`) and the DejaVu fonts. The
 * generated file is committed, so a normal build and a normal deploy never
 * run this.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const CHARS =
  Array.from({ length: 0x7f - 0x20 }, (_, i) => String.fromCharCode(0x20 + i)).join('') +
  '₹–—‘’“” •·…';

const SOURCES = {
  regular: '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
  bold: '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
};

const work = mkdtempSync(join(tmpdir(), 'gym-fonts-'));
const encoded = {};

for (const [name, source] of Object.entries(SOURCES)) {
  const output = join(work, `${name}.ttf`);
  execFileSync('pyftsubset', [
    source,
    `--text=${CHARS}`,
    `--output-file=${output}`,
    '--layout-features=*',
    '--no-hinting',
    '--desubroutinize',
  ]);
  encoded[name] = readFileSync(output).toString('base64');
}

const wrap = (data) =>
  data
    .match(/.{1,100}/g)
    .map((chunk) => `  '${chunk}' +`)
    .join('\n')
    .replace(/ \+$/, ';');

writeFileSync(
  new URL('../packages/integrations/src/pdf/fonts.ts', import.meta.url),
  `/**
 * The invoice fonts, inlined. GENERATED by scripts/build-fonts.mjs.
 * See that script, and the note in invoice.ts, for why these are base64
 * rather than files on disk.
 */

/* eslint-disable */
// prettier-ignore
export const INVOICE_FONT_REGULAR_BASE64 =
${wrap(encoded.regular)}

// prettier-ignore
export const INVOICE_FONT_BOLD_BASE64 =
${wrap(encoded.bold)}
`,
);

console.log('wrote packages/integrations/src/pdf/fonts.ts');
